// ProjetDetail.jsx
import { useParams, Link } from 'react-router-dom';
import { projects } from './projetsData'; // ou importe depuis Projets.jsx
import './ProjetDetail.css';

const statusClass = {
  'Terminé':         'pg-badge--done',
  'En cours':        'pg-badge--wip',
  'En révision':     'pg-badge--review',
  'En construction': 'pg-badge--build',
};

function ProjetDetail() {
  const { slug } = useParams();
  const project = projects.find(p => p.slug === slug);

  if (!project) {
    return (
      <div className="pd-container">
        <Link to="/projets" className="pd-back">← Retour aux projets</Link>
        <p>Projet introuvable.</p>
      </div>
    );
  }

  return (
    <div className="pd-container">
      <Link to="/projets" className="pd-back">← Retour aux projets</Link>

      <div className="pd-header">
        <h1 className="pd-title">{project.name}</h1>
        <div className="pd-meta">
          <span className={`pg-badge ${statusClass[project.status]}`}>{project.status}</span>
          <div className="pd-techs">
            {project.techs.map((tech, i) => (
              <span className="pg-tech" key={i}>{tech}</span>
            ))}
          </div>
        </div>
      </div>

      <div className="pd-accent-bar"></div>

      <p className="pd-section-label">Description</p>
      <p className="pd-desc">{project.longDesc}</p>

      {project.features?.length > 0 && (
        <>
          <hr className="pd-divider" />
          <p className="pd-section-label">Fonctionnalités</p>
          {project.features.map((f, i) => (
            <div className="pd-card" key={i}>
              <p className="pd-card-title">{f.title}</p>
              <p className="pd-card-desc">{f.desc}</p>
            </div>
          ))}
        </>
      )}

      <hr className="pd-divider" />
      <div className="pd-links">
        {project.github && (
          <a className="pd-btn pd-btn-primary" href={project.github} target="_blank" rel="noopener noreferrer">
            Voir sur GitHub →
          </a>
        )}
        {project.demo && (
          <a className="pd-btn pd-btn-secondary" href={project.demo} target="_blank" rel="noopener noreferrer">
            Démo en ligne →
          </a>
        )}
      </div>
    </div>
  );
}

export default ProjetDetail;
